<template><main class="page console-page" ref="heading" tabindex="-1"><PageHeader eyebrow="ROOT" :title="t('publicContentAdmin.title')" :description="t('publicContentAdmin.description')"><template #actions><StatusBadge v-if="draft||busy" :status="busy?'pending':'active'" :label="status"/><button type="button" @click="load">{{ t('publicContentAdmin.refresh') }}</button></template></PageHeader><p class="status" aria-live="polite">{{ status }}</p><section v-if="error" class="error" role="alert">{{ errorText }}<span v-if="error.requestId"> · {{ error.requestId }}</span></section><template v-if="draft"><nav class="tabs" aria-label="Content documents"><button v-for="name in names" :key="name" :aria-current="active===name?'page':undefined" @click="active=name">{{ t(`publicContentAdmin.documents.${name}`) }}</button></nav><SafeMarkdownEditor :id="`content-${active}`" v-model="draft[active]" :label="t(`publicContentAdmin.documents.${active}`)" :help="t('publicContentAdmin.markdownHelp')"/><label class="review"><input v-model="draft.legalReviewed" type="checkbox">{{ t('publicContentAdmin.legalReviewed') }}</label><div class="actions"><button type="button" :disabled="busy" @click="save">{{ t('publicContentAdmin.save') }}</button><button type="button" :disabled="busy||currentCanonical!==savedCanonical" @click="openPreview">{{ t('publicContentAdmin.preview') }}</button><button type="button" :disabled="busy||currentCanonical!==savedCanonical" @click="validate">{{ t('publicContentAdmin.validate') }}</button></div><SurfaceCard aria-labelledby="validation-title"><h2 id="validation-title">{{ t('publicContentAdmin.validation') }}</h2><p v-if="validationProof?.valid">{{ t('publicContentAdmin.valid') }}</p><ul v-else><li v-for="issue in localIssues" :key="issue.field+issue.code"><code>{{ issue.code }}</code> · {{ issue.field }}</li></ul></SurfaceCard><SurfaceCard class="publish"><h2>{{ t('publicContentAdmin.publish') }}</h2><label>{{ t('publicContentAdmin.priceReleaseGuid') }}<input v-model.trim="priceReleaseGuid" inputmode="numeric"></label><label>{{ t('publicContentAdmin.currentPassword') }}<input ref="passwordInput" v-model="password" type="password" autocomplete="current-password"></label><button type="button" :disabled="busy||!proofCurrent||!password" @click="publish">{{ t('publicContentAdmin.publish') }}</button><button v-if="pendingRecovery" type="button" @click="clearAttempt">{{ t('publicContentAdmin.reconcile') }}</button><p>{{ t('publicContentAdmin.productBlocker') }}</p></SurfaceCard><ContentReleaseHistory class="responsive-table" :items="history" :total="total" :busy="busy" :restore-disabled="!PUBLIC_CONTENT_APPROVAL_EVIDENCE.approved" @more="loadHistory(false)" @restore="startRestore"/></template><dialog class="responsive-dialog" ref="restoreDialog" aria-labelledby="restore-content-title" @close="restorePassword=''" @cancel.prevent="closeRestore"><h2 id="restore-content-title">{{ t('publicContentAdmin.restore') }}</h2><p>{{ t('publicContentAdmin.restoreCreatesNew') }}</p><label>{{ t('publicContentAdmin.currentPassword') }}<input v-model="restorePassword" type="password" autocomplete="current-password" autofocus></label><button :disabled="!PUBLIC_CONTENT_APPROVAL_EVIDENCE.approved" @click="restore">{{ t('publicContentAdmin.confirm') }}</button><button @click="closeRestore">{{ t('publicContentAdmin.cancel') }}</button></dialog></main></template>
<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { canonicalContentDraft, contentValidationProofMatches, createContentPublicationCoordinator, createContentValidationProof, publicContentAdminApi } from '@/api/publicContentAdmin.js'
import { publicPricingAdminApi } from '@/api/publicPricingAdmin.js'
import { PUBLIC_CONTENT_APPROVAL_EVIDENCE, validatePublicContentDraft } from '@/utils/public-content-validation.js'
import { useI18n } from '@/composables/useI18n'
import { useUserStore } from '@/stores/user'
import SafeMarkdownEditor from '@/components/public-admin/SafeMarkdownEditor.vue'
import ContentReleaseHistory from '@/components/public-admin/ContentReleaseHistory.vue'
import PageHeader from '@/components/shell/PageHeader.vue'
import SurfaceCard from '@/components/shell/SurfaceCard.vue'
import StatusBadge from '@/components/shell/StatusBadge.vue'

const { t }=useI18n(), router=useRouter(), userStore=useUserStore(), names=['home','about','terms','privacy']
const active=ref('home'), draft=ref(null), savedCanonical=ref(null), validationProof=ref(null), history=ref([]), total=ref(0), page=ref(1), busy=ref(false), error=ref(null), priceReleaseGuid=ref(''), password=ref(''), restorePassword=ref(''), restoreTarget=ref(null), heading=ref(), passwordInput=ref(), restoreDialog=ref()
let readController=new AbortController(),historyController=new AbortController(),readGeneration=0,historyGeneration=0,privilegedGeneration=0,suppressInvalidation=false
const workflow=reactive({}),coordinator=createContentPublicationCoordinator({state:workflow})
const localIssues=ref([]),status=computed(()=>busy.value?t('publicContentAdmin.loading'):draft.value?t('publicContentAdmin.revision',{revision:draft.value.revision}):''),errorText=computed(()=>t(`publicContentAdmin.errors.${error.value?.code??'request_failed'}`))
const currentCanonical=computed(()=>{try{return draft.value?canonicalContentDraft(draft.value):null}catch{return null}})
const proofCurrent=computed(()=>contentValidationProofMatches(validationProof.value,draft.value,savedCanonical.value,priceReleaseGuid.value,PUBLIC_CONTENT_APPROVAL_EVIDENCE))
const pendingRecovery=computed(()=>workflow.pendingRecovery===true)
const safe=e=>({code:/^[a-z_]{1,64}$/.test(e?.code)?e.code:'request_failed',requestId:typeof e?.requestId==='string'?e.requestId:null})
function invalidate(){if(suppressInvalidation)return;validationProof.value=null;localIssues.value=[]}
watch(draft,invalidate,{deep:true});watch(priceReleaseGuid,invalidate)
const ownsPrivilege=generation=>generation===privilegedGeneration&&userStore.user?.role==='root'
function clearPrivilegedState(){readGeneration++;historyGeneration++;privilegedGeneration++;readController.abort();historyController.abort();coordinator.cancel();suppressInvalidation=true;draft.value=null;savedCanonical.value=null;history.value=[];total.value=0;page.value=1;busy.value=false;error.value=null;priceReleaseGuid.value='';password.value='';restorePassword.value='';restoreTarget.value=null;validationProof.value=null;localIssues.value=[];restoreDialog.value?.close();suppressInvalidation=false}
watch(()=>userStore.user?.role,role=>{if(role!=='root'){clearPrivilegedState();void router.replace?.({path:'/chat',replace:true})}},{flush:'sync'})
async function loadHistory(reset=true){if(userStore.user?.role!=='root')return;historyController.abort();historyController=new AbortController();const own=++historyGeneration,generation=privilegedGeneration,next=reset?1:page.value+1;try{const out=await publicContentAdminApi.listReleases({page:next,pageSize:20,signal:historyController.signal});if(own!==historyGeneration||!ownsPrivilege(generation))return;if(reset)history.value=out.items;else history.value.push(...out.items.filter(x=>!history.value.some(y=>y.guid===x.guid)));page.value=out.page;total.value=out.total}catch(e){if(own===historyGeneration&&ownsPrivilege(generation)&&e.name!=='AbortError')error.value=safe(e)}}
async function load(){if(busy.value||userStore.user?.role!=='root')return;readController.abort();readController=new AbortController();const own=++readGeneration,generation=privilegedGeneration;busy.value=true;error.value=null;coordinator.abandon();try{const out=await publicContentAdminApi.getDraft({signal:readController.signal});if(own!==readGeneration||!ownsPrivilege(generation))return;suppressInvalidation=true;draft.value=reactive({...out});savedCanonical.value=canonicalContentDraft(out);validationProof.value=null;localIssues.value=[];await nextTick();if(!ownsPrivilege(generation))return;suppressInvalidation=false;void loadHistory(true)}catch(e){if(own===readGeneration&&ownsPrivilege(generation)&&e.name!=='AbortError')error.value=safe(e)}finally{if(own===readGeneration&&ownsPrivilege(generation))busy.value=false;suppressInvalidation=false}}
async function save(){if(busy.value||!draft.value||userStore.user?.role!=='root')return;const generation=privilegedGeneration;busy.value=true;error.value=null;try{const out=await publicContentAdminApi.saveDraft(draft.value,{signal:readController.signal});if(!ownsPrivilege(generation))return;suppressInvalidation=true;draft.value=reactive({...out});savedCanonical.value=canonicalContentDraft(out);validationProof.value=null;await nextTick();if(!ownsPrivilege(generation))return;suppressInvalidation=false}catch(e){if(!ownsPrivilege(generation))return;error.value=safe(e);if(e.code==='revision_conflict')void load()}finally{if(ownsPrivilege(generation))busy.value=false;suppressInvalidation=false}}
async function validate(){if(busy.value||!draft.value||currentCanonical.value!==savedCanonical.value||userStore.user?.role!=='root')return;const generation=privilegedGeneration;busy.value=true;error.value=null;validationProof.value=null;try{if(!priceReleaseGuid.value)throw{code:'price_release_required'};const release=await publicPricingAdminApi.getRelease(priceReleaseGuid.value,{signal:readController.signal});if(!ownsPrivilege(generation))return;const local=validatePublicContentDraft(draft.value,{modelKeys:release.items.map(x=>x.modelKey)});localIssues.value=local.issues;if(!local.valid)return;const result=await publicContentAdminApi.validate(draft.value.revision,{signal:readController.signal});if(!ownsPrivilege(generation))return;if(!result.valid){localIssues.value=result.issues;return}const canonical=currentCanonical.value,proof=await createContentValidationProof(draft.value,priceReleaseGuid.value,result);if(!ownsPrivilege(generation)||canonical!==currentCanonical.value||canonical!==savedCanonical.value)return;validationProof.value=proof}catch(e){if(ownsPrivilege(generation)&&e.name!=='AbortError')error.value=safe(e)}finally{if(ownsPrivilege(generation))busy.value=false}}
function openPreview(){if(!draft.value||currentCanonical.value!==savedCanonical.value)return;const route=router.resolve({name:'PublicContentPreview',query:{revision:draft.value.revision}});window.open(route.href,'_blank','noopener,noreferrer')}
function startRestore(item,event){coordinator.abandon();restoreTarget.value={guid:item.guid,trigger:event?.currentTarget};restorePassword.value='';restoreDialog.value?.showModal()}
function closeRestore(){restorePassword.value='';if(workflow.pendingRecovery){coordinator.abandon();void load()}restoreDialog.value?.close();const trigger=restoreTarget.value?.trigger;restoreTarget.value=null;nextTick(()=>trigger?.isConnected&&trigger.focus())}
async function publish(){if(busy.value||!proofCurrent.value||!password.value)return;let secret=password.value;password.value='';const proof=validationProof.value;busy.value=true;const out=await coordinator.publish(proof.priceReleaseGuid,proof.revision,secret);secret=null;busy.value=false;error.value=workflow.error;if(out)await load();else if(workflow.conflict)await load();await nextTick();passwordInput.value?.focus()}
async function restore(){if(!PUBLIC_CONTENT_APPROVAL_EVIDENCE.approved||busy.value||!restoreTarget.value||!restorePassword.value||!draft.value)return;let secret=restorePassword.value;restorePassword.value='';busy.value=true;const out=await coordinator.restore(restoreTarget.value.guid,draft.value.revision,secret);secret=null;busy.value=false;error.value=workflow.error;if(out){closeRestore();await load()}else if(workflow.conflict){closeRestore();await load()}}
function clearAttempt(){coordinator.abandon();void load()}
onMounted(()=>{heading.value?.focus();void load()});onBeforeUnmount(clearPrivilegedState)
</script>
<style scoped>.page{max-width:1200px;margin:auto;padding:24px;display:grid;gap:20px}.page>header{display:flex;justify-content:space-between;gap:16px}.eyebrow{letter-spacing:.12em}.tabs,.actions{display:flex;gap:8px;flex-wrap:wrap}.tabs button,.actions button,.page>header button,.publish button{min-height:44px}.review,.publish,.publish label{display:grid;gap:8px}.publish{padding:16px;border:1px solid var(--el-border-color);border-radius:12px}.publish input,dialog input{min-height:44px}.error{padding:12px;color:var(--el-color-danger);border:1px solid currentColor}.status{position:absolute;width:1px;height:1px;overflow:hidden}dialog{max-width:min(520px,calc(100vw - 32px))}@media(max-width:600px){.page{padding:16px}.page>header{flex-direction:column}}</style>
